import asynciofrom mcp_agent.app import MCPAppfrom mcp_agent.agents.agent import Agentfrom mcp_agent.workflows.llm.augmented_llm_google import GoogleAugmentedLLMapp = MCPApp(name="research_assistant")async def main():    async with app.run():        researcher = Agent(            name="business_researcher",            instruction="""            You are a business research analyst.            Your job is to analyze business questions            and provide clear, structured insights.            Focus on:            - market trends            - competitors            - opportunities            - risks            - business implications            Keep your analysis concise and practical.            """        )        async with researcher:            llm = await researcher.attach_llm(                GoogleAugmentedLLM            )            result = await llm.generate_str(                message="""                What are the three most important factors                a company should consider before entering                a new international market?                """            )            print("\n--- RESEARCH RESULT ---\n")            print(result)if __name__ == "__main__":    asyncio.run(main())